"use strict";
const fs = require("node:fs");
const path = require("node:path");
const file = path.join(__dirname, "motto.txt");
exports.motto = function motto() {
  try {
    return fs.readFileSync(file, "utf8").trim();
  } catch {
    return "no motto";
  }
};
exports.strict = function strict() {
  return fs.readFileSync(file, "utf8").length;
};
